import{_ as e,a as t,c as o,ac as r}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"文档站内容、构建与发布排错","description":"内容元数据、MkDocs导航、基路径、依赖、托管、缓存和历史主题边界。","frontmatter":{"title":"文档站内容、构建与发布排错","description":"内容元数据、MkDocs导航、基路径、依赖、托管、缓存和历史主题边界。","showdocs":{"topics":[{"id":"blog","title":"静态站点与文档站","link":"/topics/blog/"}],"kind":"静态站点与文档站上手与对象","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"静态站点与文档站：内容、构建与地址","summary":"内容元数据、MkDocs导航、基路径、依赖、托管、缓存和历史主题边界。","status":"active","related":[{"title":"静态站点与文档站：完整实践与解答","link":"/tools/documentation/blog/practice/application","kind":"静态站点与文档站完整实践与解答","scope":"general","audience":"general"}],"prev":false,"next":{"text":"静态站点与文档站：完整实践与解答","link":"/tools/documentation/blog/practice/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"静态站点与文档站：完整实践与解答","link":"/tools/documentation/blog/practice/application"}},"headers":[],"relativePath":"tools/documentation/blog/site-build-and-publishing.md","filePath":"tools/documentation/blog/site-build-and-publishing.md"}'),i={name:"tools/documentation/blog/site-build-and-publishing.md"};function n(l,a,s,p,c,d){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="文档站内容、构建与发布排错" tabindex="-1">文档站内容、构建与发布排错 <a class="header-anchor" href="#文档站内容、构建与发布排错" aria-label="Permalink to &quot;文档站内容、构建与发布排错&quot;">​</a></h1><h2 id="part-1" tabindex="-1">区分内容、构建输出与基路径 <a class="header-anchor" href="#part-1" aria-label="Permalink to &quot;区分内容、构建输出与基路径 {#part-1}&quot;">​</a></h2><p>需能阅读 YAML 与 Markdown 相对链接。<a href="/tools/documentation/blog/practice/application#source">两页文档站示例</a>固定 MkDocs 1.6.1，使用 <code>pages/</code> 存源码、<code>output/</code> 存构建结果，并演示 <code>/handbook/</code> 子路径；先对照 <code>mkdocs.yml</code>、页面链接和 README，再判断导航与输出地址。 示例未在本轮执行。</p><h3 id="part-1-pipeline" tabindex="-1">静态站点 构建链 <a class="header-anchor" href="#part-1-pipeline" aria-label="Permalink to &quot;静态站点 构建链 {#part-1-pipeline}&quot;">​</a></h3><p>静态站点构建链把内容、模板和配置转换为HTML及资源文件。源码目录与输出目录要分开，输出可重新生成；把构建成功当作发布成功会遗漏托管路径和缓存问题。</p><h3 id="part-1-content" tabindex="-1">静态站点 内容模型 <a class="header-anchor" href="#part-1-content" aria-label="Permalink to &quot;静态站点 内容模型 {#part-1-content}&quot;">​</a></h3><p>静态站点内容模型区分文章元数据、正文与导航。日期是发布语义而非文件修改时间，草稿是否进入输出由生成器规则决定；不把历史主题的frontmatter字段当作所有站点通用标准。</p><h3 id="part-1-base" tabindex="-1">静态站点 基路径 <a class="header-anchor" href="#part-1-base" aria-label="Permalink to &quot;静态站点 基路径 {#part-1-base}&quot;">​</a></h3><p>静态站点基路径决定子目录托管下资源地址。例如站点位于/handbook/时根相对/assets会跳出子目录；使用生成器支持的相对链接和site_url，避免本地可读但部署后资源404。</p><p><span id="part-3-sources"></span></p><p><span id="part-2-sources"></span></p><h3 id="part-1-sources" tabindex="-1">依据与适用范围 <a class="header-anchor" href="#part-1-sources" aria-label="Permalink to &quot;依据与适用范围 {#part-1-sources}&quot;">​</a></h3><ul><li><a href="https://www.mkdocs.org/user-guide/configuration/" target="_blank" rel="noopener noreferrer">本课官方依据</a>，资料核对日2026-10-17。</li></ul><p>以上依据用于解释本文列明的规则；示例未执行，不代表产品全部能力或跨平台验证。历史资料的版本、账号与界面位置需按目标环境确认。</p><h2 id="part-2" tabindex="-1">配置导航、依赖与发布资料 <a class="header-anchor" href="#part-2" aria-label="Permalink to &quot;配置导航、依赖与发布资料 {#part-2}&quot;">​</a></h2><h3 id="part-2-navigation" tabindex="-1">MkDocs nav 配置 <a class="header-anchor" href="#part-2-navigation" aria-label="Permalink to &quot;MkDocs nav 配置 {#part-2-navigation}&quot;">​</a></h3><p>MkDocs的nav配置指定页面树及显示标题，路径相对docs_dir。文件存在不等于进入导航，导航引用不存在文件也会失败；本例明确两页顺序，不自动把全部草稿收录。</p><h3 id="part-2-dependencies" tabindex="-1">静态站点 依赖声明 <a class="header-anchor" href="#part-2-dependencies" aria-label="Permalink to &quot;静态站点 依赖声明 {#part-2-dependencies}&quot;">​</a></h3><p>静态站点依赖声明应固定选定生成器和主题，升级时一起核对插件。示例选择MkDocs1.6.1作为教学版本而不称最新，标准主题避免隐藏主题下载；本轮不安装依赖。</p><h3 id="part-2-publishing" tabindex="-1">静态站点 发布资料 <a class="header-anchor" href="#part-2-publishing" aria-label="Permalink to &quot;静态站点 发布资料 {#part-2-publishing}&quot;">​</a></h3><p>静态站点发布资料至少包含构建输入、输出路径和托管前缀。发布需要额外授权与账号，本课只列读者自跑命令，不调用托管平台或启动预览；上传目录不能误指向含源码秘密的根目录。</p><h2 id="part-3" tabindex="-1">排查主题迁移、断链与缓存 <a class="header-anchor" href="#part-3" aria-label="Permalink to &quot;排查主题迁移、断链与缓存 {#part-3}&quot;">​</a></h2><h3 id="part-3-theme" tabindex="-1">静态站点 历史主题 <a class="header-anchor" href="#part-3-theme" aria-label="Permalink to &quot;静态站点 历史主题 {#part-3-theme}&quot;">​</a></h3><p>静态站点历史主题的字段、短代码和评论服务属于特定版本契约。旧Hugo Jane与Jekyll模板可帮助理解文章结构，迁移时需逐项找对应能力，不把主题配置直接塞入MkDocs。</p><h3 id="part-3-broken" tabindex="-1">静态站点 链接失效 <a class="header-anchor" href="#part-3-broken" aria-label="Permalink to &quot;静态站点 链接失效 {#part-3-broken}&quot;">​</a></h3><p>静态站点链接失效要区分源码路径不存在、输出扩展变化、大小写差异和基路径错误。Windows本地文件能打开不证明大小写敏感托管环境可达；修正文链接而非只在构建输出补文件。</p><h3 id="part-3-cache" tabindex="-1">静态站点 缓存 <a class="header-anchor" href="#part-3-cache" aria-label="Permalink to &quot;静态站点 缓存 {#part-3-cache}&quot;">​</a></h3><p>静态站点缓存会让读者看到旧HTML与新资源混搭。带内容摘要的资源名能降低错配，入口HTML需要合适的更新策略；本例不配置CDN，不能从静态配置宣称线上刷新已生效。</p>',28)])])}const b=e(i,[["render",n]]);export{u as __pageData,b as default};
